// One Slack message listing new comments that match the filter, grouped by video, most liked first. Nothing: no message.
const filter = String($('Settings').first().json.filter ?? '').trim().toLowerCase();
const comments = $input.all().map((i) => i.json).filter((c) => c.found !== false && c.text && (!filter || c.text.toLowerCase().includes(filter)));
if (comments.length === 0) return [];
const byVideo = {};
for (const c of comments) (byVideo[c.videoId] ??= []).push(c);
const blocks = Object.values(byVideo).map((list) => {
  list.sort((a, b) => (b.likes ?? 0) - (a.likes ?? 0));
  const lines = list.slice(0, 15).map((c) => `• ${c.text.replace(/\s+/g, ' ').slice(0, 220)} (:+1: ${c.likes ?? 0}, :speech_balloon: ${c.replyCount ?? 0}, ${c.publishedText ?? (c.publishedAt ?? '').slice(0, 10)})`);
  if (list.length > 15) lines.push(`…and ${list.length - 15} more`);
  return `*<${list[0].videoUrl}|${(list[0].videoTitle ?? list[0].videoId).replace(/[<>|]/g, ' ')}>*: ${list.length} new comment${list.length > 1 ? 's' : ''}\n${lines.join('\n')}`;
});
return [{ json: { text: `:tv: *New YouTube comments*${filter ? ` containing "${filter}"` : ''}\n\n${blocks.join('\n\n')}`, newComments: comments.length } }];
